//! Radix-2 FFTs over the BLS12-381 scalar field and over G1, for EIP-7594 cells.
//!
//! The domain is the multiplicative subgroup of order 8192 (`ext_size`, a blob extended
//! by factor 2), generated by w = 7^((r - 1) / 8192), the consensus-specs
//! `PRIMITIVE_ROOT_OF_UNITY` construction. `Roots` holds w^0 .. w^8192 in natural order
//! (the extra w^8192 = 1 lets the inverse transform read w^-i as roots[8192 - i]).
//!
//! Every transform here is in place, iterative (bit-reversal permutation, then
//! log2(n) butterfly passes), and works for any power-of-two size up to 8192 by
//! striding through the roots. Output is in natural order:
//! out[k] = sum_i in[i] * w_n^(i k) with w_n the root of order n.

const std = @import("std");
const assert = std.debug.assert;
const bls = @import("../bls12_381/root.zig");
const kzg = @import("root.zig");

const Fr = bls.Fr;
const G1 = bls.G1;

pub const ext_size = 2 * kzg.field_elements_per_blob;
pub const ext_size_log2 = 13;

/// Powers w^0 .. w^ext_size of the order-8192 root of unity, natural order.
pub const Roots = [ext_size + 1]Fr;

/// The spec's primitive root of the scalar field.
pub const primitive_root = 7;

comptime {
    assert(ext_size == 1 << ext_size_log2);
    assert((kzg.bls_modulus - 1) % ext_size == 0);
}

/// Fills `roots` with w^i for i in 0..=8192.
pub fn fill_roots(roots: *Roots) void {
    const omega = Fr.from_int_comptime(primitive_root).pow((kzg.bls_modulus - 1) / ext_size);
    var power = Fr.one;
    for (roots) |*root| {
        root.* = power;
        power = power.mul(omega);
    }
    assert(roots[ext_size].eql(Fr.one)); // omega^8192 = 1.
    assert(!roots[ext_size / 2].eql(Fr.one)); // Order exactly 8192: w^4096 = -1.
}

/// `bits`-bit reversal of `value` (`value < 2^bits`).
pub fn reverse_bits(value: u32, bits: u5) u32 {
    assert(bits > 0 and bits <= 16);
    assert(value < @as(u32, 1) << bits);
    const reversed = @bitReverse(value) >> @intCast(@as(u6, 32) - bits);
    assert(reversed < @as(u32, 1) << bits);
    return reversed;
}

/// Permutes `values` (power-of-two length >= 2) into bit-reversal order in place.
pub fn bit_reverse_permute(comptime T: type, values: []T) void {
    assert(std.math.isPowerOfTwo(values.len));
    assert(values.len >= 2 and values.len <= 1 << 16);
    const bits: u5 = @intCast(std.math.log2_int(usize, values.len));
    for (0..values.len) |index| {
        const reversed = reverse_bits(@intCast(index), bits);
        if (index < reversed) std.mem.swap(T, &values[index], &values[reversed]);
    }
}

const Direction = enum { forward, inverse };

fn check_size(length: usize) void {
    assert(std.math.isPowerOfTwo(length));
    assert(length <= ext_size);
}

/// Twiddle w_n^(j) for a pass of half-size `half` (n = 2 * half), in either direction.
inline fn twiddle(roots: *const Roots, direction: Direction, half: usize, j: usize) Fr {
    const index = j * (ext_size / (2 * half));
    assert(index < ext_size);
    return switch (direction) {
        .forward => roots[index],
        .inverse => roots[ext_size - index],
    };
}

fn transform_fr(roots: *const Roots, values: []Fr, direction: Direction) void {
    check_size(values.len);
    if (values.len < 2) return;
    bit_reverse_permute(Fr, values);
    var half: usize = 1;
    while (half < values.len) : (half *= 2) {
        var start: usize = 0;
        while (start < values.len) : (start += 2 * half) {
            for (0..half) |j| {
                const w = twiddle(roots, direction, half, j);
                const top = &values[start + j];
                const bottom = &values[start + j + half];
                const product = bottom.mul(w);
                bottom.* = top.sub(product);
                top.* = top.add(product);
            }
        }
    }
}

/// Forward FFT in place: coefficients to evaluations over the order-n subgroup.
pub fn fft_fr(roots: *const Roots, values: []Fr) void {
    transform_fr(roots, values, .forward);
}

/// Inverse FFT in place: evaluations to coefficients (scaled by 1/n).
pub fn ifft_fr(roots: *const Roots, values: []Fr) void {
    transform_fr(roots, values, .inverse);
    if (values.len == 0) return;
    const inverse_n = Fr.from_int(values.len).inverse();
    assert(inverse_n.mul(Fr.from_int(values.len)).eql(Fr.one));
    for (values) |*value| value.* = value.mul(inverse_n);
}

fn transform_g1(roots: *const Roots, values: []G1, direction: Direction) void {
    check_size(values.len);
    if (values.len < 2) return;
    bit_reverse_permute(G1, values);
    var half: usize = 1;
    while (half < values.len) : (half *= 2) {
        var start: usize = 0;
        while (start < values.len) : (start += 2 * half) {
            for (0..half) |j| {
                const top = &values[start + j];
                const bottom = &values[start + j + half];
                // The first twiddle of every block is 1: skip the scalar multiplication.
                const product = if (j == 0)
                    bottom.*
                else
                    bls.g1.mul_glv(bottom.*, twiddle(roots, direction, half, j).to_int());
                bottom.* = top.sub(product);
                top.* = top.add(product);
            }
        }
    }
}

/// Forward FFT of G1 points in place. Points must be in the order-r subgroup (GLV).
pub fn fft_g1(roots: *const Roots, values: []G1) void {
    transform_g1(roots, values, .forward);
}

/// Inverse FFT of G1 points in place without the 1/n scaling (FK20 folds it into the
/// scalars, saving n scalar multiplications).
pub fn ifft_g1_unscaled(roots: *const Roots, values: []G1) void {
    transform_g1(roots, values, .inverse);
}

const testing = std.testing;
const Prng = @import("../../../testing/prng.zig").Prng;

var test_roots: Roots = undefined;
var test_roots_ready = false;
var test_values: [ext_size]Fr = undefined;

fn shared_roots() *const Roots {
    if (!test_roots_ready) {
        fill_roots(&test_roots);
        test_roots_ready = true;
    }
    return &test_roots;
}

/// Naive O(n^2) DFT used as the oracle.
fn naive_dft(roots: *const Roots, input: []const Fr, output: []Fr) void {
    assert(input.len == output.len);
    const stride = ext_size / input.len;
    for (output, 0..) |*out, k| {
        var sum = Fr.zero;
        for (input, 0..) |value, i| sum = sum.add(value.mul(roots[(i * k % input.len) * stride]));
        out.* = sum;
    }
}

test "fft: roots of unity match the blob domain" {
    const roots = shared_roots();
    // w^2 generates the 4096 blob domain, so its square chain matches blob.zig's omega.
    const omega_4096 = Fr.from_int_comptime(primitive_root)
        .pow((kzg.bls_modulus - 1) / kzg.field_elements_per_blob);
    try testing.expect(roots[2].eql(omega_4096));
    try testing.expect(roots[ext_size / 2].eql(Fr.one.neg()));
    try testing.expect(roots[1].mul(roots[ext_size - 1]).eql(Fr.one));
}

test "fft: bit reversal" {
    try testing.expectEqual(@as(u32, 64), reverse_bits(1, 7));
    try testing.expectEqual(@as(u32, 127), reverse_bits(127, 7));
    try testing.expectEqual(@as(u32, 0b0011), reverse_bits(0b1100, 4));
    var values = [8]u8{ 0, 1, 2, 3, 4, 5, 6, 7 };
    bit_reverse_permute(u8, &values);
    try testing.expectEqualSlices(u8, &.{ 0, 4, 2, 6, 1, 5, 3, 7 }, &values);
    bit_reverse_permute(u8, &values);
    try testing.expectEqualSlices(u8, &.{ 0, 1, 2, 3, 4, 5, 6, 7 }, &values);
}

test "fft: matches the naive DFT and inverts (seeded)" {
    const roots = shared_roots();
    var prng = Prng.init(0xff7);
    var input: [64]Fr = undefined;
    var output: [64]Fr = undefined;
    var expected: [64]Fr = undefined;
    for ([_]usize{ 1, 2, 4, 8, 32, 64 }) |size| {
        for (input[0..size]) |*value| value.* = Fr.from_int(prng.int(u256));
        @memcpy(output[0..size], input[0..size]);
        fft_fr(roots, output[0..size]);
        naive_dft(roots, input[0..size], expected[0..size]);
        for (output[0..size], expected[0..size]) |got, want| try testing.expect(got.eql(want));
        ifft_fr(roots, output[0..size]);
        for (output[0..size], input[0..size]) |got, want| try testing.expect(got.eql(want));
    }
}

test "fft: full 8192-point round trip and low-degree evaluation" {
    const roots = shared_roots();
    const values = &test_values;
    // p(x) = 3 + 5x evaluates to 3 + 5 w^k.
    @memset(values, Fr.zero);
    values[0] = Fr.from_int(3);
    values[1] = Fr.from_int(5);
    fft_fr(roots, values);
    for ([_]usize{ 0, 1, 77, 4096, 8191 }) |k| {
        try testing.expect(values[k].eql(Fr.from_int(3).add(Fr.from_int(5).mul(roots[k]))));
    }
    ifft_fr(roots, values);
    try testing.expect(values[0].eql(Fr.from_int(3)) and values[1].eql(Fr.from_int(5)));
    for (values[2..]) |value| try testing.expect(value.is_zero());
}

test "fft: G1 transform is linear in the scalar FFT" {
    // FFT of [a_i] G equals [FFT(a)_k] G; the inverse undoes it up to the factor n.
    const roots = shared_roots();
    var prng = Prng.init(0x61ff7);
    const size = 8;
    var scalars: [size]Fr = undefined;
    var points: [size]G1 = undefined;
    const generator = bls.g1.generator.to_jacobian();
    for (&scalars, &points) |*scalar, *point| {
        scalar.* = Fr.from_int(prng.int(u64));
        point.* = generator.mul(scalar.to_int());
    }
    fft_g1(roots, &points);
    fft_fr(roots, &scalars);
    for (scalars, points) |scalar, point| {
        try testing.expect(point.eql(generator.mul(scalar.to_int())));
    }
    ifft_g1_unscaled(roots, &points);
    ifft_fr(roots, &scalars);
    for (scalars, points) |scalar, point| {
        try testing.expect(point.eql(generator.mul(scalar.mul(Fr.from_int(size)).to_int())));
    }
}
